mapper.select:
        SELECT
        
        FROM contract_collection AS cle
        LEFT JOIN contract_project AS cp ON cle.project_id = cp.id

        
            LEFT JOIN sys_project_user_link AS pul ON cle.project_id = pul.project_id
            AND pul.bool_delete_enum = 0
        

        
        LEFT JOIN contract_waste AS cw on cle.contract_waste_id = cw.id
        LEFT JOIN sys_branch_company as bc on bc.id = cle.collection_unit_id
        WHERE cle.bool_delete_enum = 0

        
            AND cle.type = #{type}
        

        
            AND ((cle.type = 1 AND pul.user_id = #{userId}) OR cle.type IN (2,4))
        

        
            and cp.business_type = #{businessType}
        

        
            and cle.project_id = #{projectId}
        

        
            and cp.business_type = #{businessType}
        

        
            and cle.contract_waste_id = #{contractWasteId}
        

        
            and cle.collection_unit_id = #{collectionUnitId}
        

        
            and cle.collection_date >= #{startDate}
        

        
            and cle.collection_date <= #{endDate}
        

        
            and cle.audit_status = #{auditStatus}
        

        
            and (cp.name like concat('%',#{name},'%')
            or cp.short_name like concat('%',#{name},'%')
            or cw.purchaser like concat('%',#{name},'%')
            )
        

        
            and bc.name like concat('%',#{contractSignBodyName},'%')
        
        GROUP BY cle.id
        ORDER BY cle.audit_status ASC, cle.collection_date DESC, cle.id DESC

        select
        IFNULL(sum(collection_amount),0)
        from contract_collection
        where bool_delete_enum = 0

        
            and project_id = #{projectId}
        
        
            and audit_status = #{auditStatus}

SELECT p.id, p.id AS 'project.id', p.name AS 'project.name', p.short_name AS 'project.shortName', p.serial_number AS 'project.serialNumber', (SELECT `name` FROM sys_user WHERE bool_delete_enum = 0 AND id = p.project_manager_id ) AS project_manager_name, p.signing_date, p.business_type, p.contract_amount, p.happened_amount, (SELECT IFNULL(SUM(collection_amount), 0 ) FROM contract_collection WHERE project_id = p.id and bool_delete_enum = 0 and audit_status = 2) as collection_amount FROM contract_project AS p
INNER JOIN ( ( SELECT id AS project_id FROM contract_project WHERE bool_delete_enum = 0 AND user_id = #{userId}) UNION (SELECT project_id FROM sys_project_user_link WHERE bool_delete_enum = 0 AND user_id = #{userId}) ) AS pids ON p.id = pids.project_id
WHERE p.bool_delete_enum = 0
AND p.id = #{projectId}
AND DATE_FORMAT( p.create_time, '%Y' ) = #{year}
AND p.bool_arrears = #{boolArrears}
order by p.id desc

SELECT t.month, sum(t.collection_amount) collection_amount, sum(t.payment_amount) payment_amount FROM (SELECT collection.*, 0 AS payment_amount FROM ( SELECT DATE_FORMAT( cc.collection_date, '%m' ) AS MONTH, SUM( cc.collection_amount ) AS collection_amount FROM contract_collection AS cc INNER JOIN contract_project AS cp ON cc.project_id = cp.id AND cp.bool_delete_enum = 0 WHERE cc.bool_delete_enum = 0 AND cc.audit_status = 2
AND DATE_FORMAT( cc.collection_date, '%Y' ) = #{year}
AND cc.collection_unit_id = #{branchCompanyId}
GROUP BY MONTH ) AS collection
UNION ALL
SELECT payment.`month`, 0 collection_amount, payment.payment_amount FROM ( SELECT DATE_FORMAT( payment_date, '%m' ) AS month, SUM( actually_payment_amount ) AS payment_amount FROM contract_supplier_payment WHERE bool_delete_enum = 0 AND audit_status = 2
AND DATE_FORMAT( payment_date, '%Y' ) = #{year}
AND payment_unit_id = #{branchCompanyId}
GROUP BY month ) AS payment ) AS t GROUP BY t.month

select * from contract_collection where bool_delete_enum = 0
and project_id = #{projectId}
and payment_unit like concat('%',#{remark},'%')
and collection_mode = #{collectionMode}
and collection_date >= DATE_FORMAT(#{startDate},'%Y-%m-%d')
and collection_date <= DATE_FORMAT(#{endDate},'%Y-%m-%d')
